let chestDemo=null,chestDemoKey='';
function startChestPractice(kind){chestDemo=createRoom('CHEST-DEMO',42,true,true);const p=addPlayer(chestDemo,'preview','开箱演练');p.weapons=[...FUSIONS[kind].needs];p.weaponTiers=[4,4];startWave(chestDemo);chestDemo.random=()=>0;chestDemo.total=1;chestDemo.nextSpawn=1e9;chestDemo.chests=[{id:'practice-chest',x:600,y:330,boss:'演练首领'}];chestDemoKey='';$('chest-demo').showModal();renderChestPractice();}
function renderChestPractice(){if(!chestDemo)return;const p=chestDemo.players[0],key=JSON.stringify([chestDemo.phase,p.pendingUpgrades,p.weapons,p.rewards]);if(key===chestDemoKey)return;chestDemoKey=key;$('chest-demo-choices').classList.toggle('hidden',!p.rewardPending);$('chest-demo-status').textContent=p.rewardPending?'宝箱打开了 · 选择一件奖励':p.weapons.some(k=>FUSIONS[k])?`融合完成：${p.weapons.filter(Boolean).map(k=>weaponDefinition(k).name).join(' ＋ ')} · 原料已消耗`:'角色正在走向宝箱…';$('chest-demo-loadout').textContent=p.weapons.filter(Boolean).map(k=>weaponDefinition(k).name+' '+weaponStats(k,4).tierName).join(' ＋ ');
$('chest-demo-cards').innerHTML=p.rewards.map((reward,n)=>{const weapon=typeof reward==='object',d=weapon?weaponStats(reward.kind,reward.tier):ITEMS[reward];return `<button class="reward-card ${reward.type==='fusion'?'fusion-reward':''}" data-demo-reward="${n}">${icon(d.icon,weapon?d.color:d.color)}<strong>${escape(d.name)}</strong><span class="reward-description">${escape(weapon?d.desc:d.text)}</span><span class="reward-outcome">${reward.type==='fusion'?'消耗这两把传说武器 → 融合':'领取这件奖励'}</span></button>`;}).join('');}
$('close-chest-demo').onclick=()=>$('chest-demo').close();$('chest-demo-cards').onclick=e=>{const b=e.target.closest('[data-demo-reward]');if(!b||!chestDemo)return;action(chestDemo,chestDemo.players[0],{type:'reward',index:Number(b.dataset.demoReward)});renderChestPractice();};
