document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const gates={'expedition-preview-button':Object.keys(ITEMS).every(k=>known('items',k)),'recycling-preview-button':Object.keys(WEAPONS).every(k=>known('weapons',k)),'fx-button':Object.keys(WEAPONS).every(k=>known('weapons',k))};if(Object.hasOwn(gates,b.id)&&!gates[b.id]){e.stopImmediatePropagation();e.preventDefault();toast('先在正式出征中发现装备，完整演练会在图鉴收集完成后开放。');}},true);
