$('sound-samples').innerHTML=samples.map(([label,event])=>`<button class="secondary" data-sound="${escape(JSON.stringify({...event,local:true}))}">${label}</button>`).join('');renderAudio();
let machineKey='',machineTimer=null,machineGeneration=0;
function closeMachine(){audio.cancel('spin');clearTimeout(machineTimer);machineGeneration++;$('reward-machine').close();}
function revealMachine(){audio.cancel('spin');if($('reward-machine').classList.contains('spinning'))audio.play({type:'reveal'});clearTimeout(machineTimer);$('reward-machine').classList.remove('spinning');$('machine-reels').classList.add('hidden');$('machine-choices').classList.remove('hidden');$('machine-status').textContent=$('reward-machine').classList.contains('boss-chest')?'宝箱已打开 · 选择一件首领战利品':'补给已揭晓 · 选择一件加入你的构筑';$('machine-skip').classList.add('hidden');}
function updateMachine(){
  const p=me();if(!p?.rewardPending||['victory','defeat'].includes(state?.phase)){closeMachine();return;}
  const key=JSON.stringify([state.code,playerId,p.level,p.pendingUpgrades,p.rewardSource,p.rewards]);if(key===machineKey){$('machine-choices').innerHTML=$('reward-choices').innerHTML.replaceAll('data-reward=','data-slot-reward=');return;}machineKey=key;closeMachine();
  const boss=p.rewardSource==='boss';$('reward-machine').classList.toggle('boss-chest',boss);$('reward-machine').querySelector('.machine-note').textContent=boss?'融合会消耗两把配方原料；其他奖励不消耗已有武器。':'已有武器不降品质 · 动画不消耗经验，也不会改变奖励';const weights=rewardTierWeights(p.level),generation=machineGeneration;
  $('machine-level').textContent=boss?`开箱额外奖励 · 传说配方就绪时 ${Math.round(FUSION_CHANCE*100)}% 概率出现融合选项`:`LV ${p.level} · 随机奖励品质：${weights.map((v,n)=>v?`${TIERS[n+1].name} ${v}%`:null).filter(Boolean).join(' / ')}`;
  $('machine-title').textContent=boss?`${p.rewardBoss||'首领'}的宝箱`:'命运转轮 · 升级了';$('reward-machine').querySelector('.machine-kicker').textContent=boss?'首领战利品 · 额外奖励三选一':'升级补给 · 三选一';$('machine-status').textContent=boss?'正在打开首领宝箱…':'正在揭晓你的升级奖励…';$('machine-skip').classList.remove('hidden');$('machine-reels').classList.remove('hidden');$('machine-choices').classList.add('hidden');$('reward-machine').classList.add('spinning');
  const kinds=['pistol','battery','wand','eye','rocket','hat','ghostaxe','scope'];
  $('machine-reels').innerHTML=boss?'<div class="loot-chest"><div class="chest-rays">✦　✧　✦</div><div class="chest-lid"></div><div class="chest-body"><i></i></div></div>':[0,1,2].map(n=>`<div class="machine-reel"><div class="reel-strip">${Array.from({length:16},(_,j)=>`<div style="color:${TIERS[j%4+1].color}">${icon(kinds[(j+n*3)%kinds.length])}</div>`).join('')}</div><span class="reel-marker">◆</span></div>`).join('');
  $('machine-choices').innerHTML=$('reward-choices').innerHTML.replaceAll('data-reward=','data-slot-reward=');$('reward-machine').showModal();
  if(experience.settings.quick||matchMedia('(prefers-reduced-motion: reduce)').matches)revealMachine();else {audio.play({type:boss?'chestOpen':'spin'});machineTimer=setTimeout(()=>{if(generation===machineGeneration)revealMachine();},1800);}
}
$('machine-discard').onclick=()=>{if(me()?.rewardPending)send({type:'skipReward'});};
$('machine-skip').onclick=revealMachine;$('machine-close').onclick=closeMachine;
$('reward-machine').addEventListener('cancel',e=>{if($('reward-machine').classList.contains('spinning')){e.preventDefault();revealMachine();}});
$('machine-choices').onclick=e=>{const b=e.target.closest('[data-slot-reward]');if(!b||!me()?.rewardPending)return;for(const card of $('machine-choices').querySelectorAll('button'))card.disabled=true;$('machine-status').textContent='正在领取补给…';send({type:'reward',index:Number(b.dataset.slotReward),merge:b.dataset.merge==='true',stash:experience.settings.stash});};
const invite=new URL(location.href).searchParams.get('room');if(invite)$('room-code').value=invite.toUpperCase();
$('nickname').value=localStorage.getItem('lastpack-name')||'';
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const me=()=>state?.players.find(p=>p.id===playerId);
const canManageWeapons=()=>['prepare','upgrade','battle'].includes(state?.phase);
const canEquip=()=>['prepare','upgrade'].includes(state?.phase);
const movement=setupMovement({getPlayer:me,getPhase:()=>state?.phase,send:data=>{if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify(data));}});
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function send(data){if(ws?.readyState!==WebSocket.OPEN){toast('连接正在恢复，请稍等');return;}ws.send(JSON.stringify(data));}
function pendingUI(on){pending=on;['solo-button','create-button','join-button'].forEach(id=>$(id).disabled=on);}
function openConnection(initial){
  clearTimeout(reconnectTimer);manualClose=false;pendingUI(true);
  ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/socket`);
  const socket=ws;
  ws.onopen=()=>{if(socket!==ws)return; $('connection').textContent='CONNECTED / 在线';ws.send(JSON.stringify({type:'profile',profileToken}));if(initial.type!=='profile')ws.send(JSON.stringify(initial)); };
  ws.onmessage=event=>{
    if(socket!==ws)return;
    let msg;try{msg=JSON.parse(event.data);}catch{return;}
    if(msg.type==='profile'){profileToken=msg.profileToken;localStorage.setItem('lastpack-profile',profileToken);career.update(msg.profile,msg.forgeResult);experience.update();if($('weapon-catalog').open)renderCatalog();if($('item-catalog').open)renderItems();if(initial.type==='profile')pendingUI(false);if(state)render();}
    if(msg.type==='welcome'){movement.onWelcome(initial.type==='resume');automation.onWelcome(initial.type==='resume');token=msg.token;playerId=msg.playerId;sessionStorage.setItem('lastpack-session',token);localStorage.setItem('lastpack-checkpoint',token);pendingUI(false);$('landing').classList.add('hidden');$('game').classList.remove('hidden');window.scrollTo(0,0);}
    if(msg.type==='state'){const previous=state;state=msg.state;const now=performance.now();presentation.push(state,now);audio.push(state,playerId);music.setScene(state);if($('sound-settings').open)renderAudio();if(state.phase!=='battle'||previous?.phase!==state.phase||now-lastHud>=200||previous?.players.find(p=>p.id===playerId)?.controlMode!==me()?.controlMode){render();lastHud=now;}}
    if(msg.type==='error'){toast(msg.message);career.failed();pendingUI(false);for(const card of $('machine-choices').querySelectorAll('button'))card.disabled=false;if($('reward-machine').open)$('machine-status').textContent=msg.message;if(initial.type==='resume' && msg.message.includes('过期')){localStorage.removeItem('lastpack-checkpoint');resumeButton.classList.add('hidden');manualClose=true;ws.close();resetUI();openConnection({type:'profile'});}}
    if(msg.type==='suspended'){localStorage.setItem('lastpack-checkpoint',msg.token);resetUI();resumeButton.classList.remove('hidden');toast('出征已保存，下次可继续。');}
    if(msg.type==='left'){localStorage.removeItem('lastpack-checkpoint');resumeButton.classList.add('hidden');resetUI();}
  };
  ws.onclose=event=>{
    if(socket!==ws)return;movement.reset();
    pendingUI(false);if(manualClose)return;
    $('connection').textContent='OFFLINE / 已离线';
    if(event.code===4001){toast('这个角色已在另一窗口恢复');manualClose=true;resetUI();openConnection({type:'profile'});return;}
    if(token){toast('连接断开，正在恢复房间…');reconnectTimer=setTimeout(()=>openConnection({type:'resume',token}),1600);}
    else reconnectTimer=setTimeout(()=>openConnection({type:'profile'}),2000);
  };
  ws.onerror=()=>{};
}
function resetUI(){shell.closePanels();music.setScene('menu');audio.reset();closeMachine();machineKey='';movement.reset();token=null;state=null;playerId=null;selected=null;lastPhase=null;sessionStorage.removeItem('lastpack-session');$('landing').classList.remove('hidden');$('game').classList.add('hidden');$('connection').textContent='CO-OP SURVIVAL';bagKey=weaponsKey=teamKey=detailKey=rewardKey='';pendingUI(false);shell.render();window.scrollTo(0,0);}
const resumeButton=document.createElement('button');resumeButton.className='secondary';resumeButton.textContent='继续上次出征';resumeButton.id='resume-expedition';resumeButton.classList.toggle('hidden',!localStorage.getItem('lastpack-checkpoint'));$('landing-career').after(resumeButton);resumeButton.onclick=()=>{const saved=localStorage.getItem('lastpack-checkpoint');if(saved)openConnection({type:'resume',token:saved});};
const suspendButton=document.createElement('button');suspendButton.className='text-button';suspendButton.textContent='保存并离开（单人）';suspendButton.id='suspend-expedition';$('help-button').before(suspendButton);suspendButton.onclick=()=>send({type:'suspend'});
function enter(solo,join=false){if(pending)return;const name=$('nickname').value.trim()||'幸存者';localStorage.setItem('lastpack-name',name);const code=$('room-code').value.trim().toUpperCase();if(join && !/^[A-F0-9]{6}$/.test(code)){toast('请输入完整的 6 位房间码');return;}if(ws){manualClose=true;ws.close();}openConnection(join?{type:'join',name,code}:{type:'create',name,solo});}
$('solo-button').onclick=()=>enter(true);$('create-button').onclick=()=>enter(false);$('join-button').onclick=()=>enter(false,true);$('room-code').onkeydown=e=>{if(e.key==='Enter')enter(false,true);};
$('leave-button').onclick=()=>send({type:'leave'});
$('copy-code').onclick=async()=>{if(!state)return;const url=`${location.origin}/?room=${state.code}`;try{await navigator.clipboard.writeText(state.solo?state.code:url);toast(state.solo?'单人房间无需邀请':'邀请链接已复制，发给队友即可加入');}catch{toast(`房间码：${state.code}`);}};
function renderCatalog(){const tier=Number($('catalog-tier').value),category=$('catalog-category').value,entries=Object.entries(WEAPONS).filter(([kind])=>category==='all'||weaponCategory(kind)===category).sort(([a],[b])=>Number(known('weapons',b))-Number(known('weapons',a)));$('catalog-count').textContent=entries.length+' 种武器';$('catalog-list').innerHTML=entries.map(([kind])=>{if(!known('weapons',kind))return unknownCard();const w=weaponStats(kind,tier);return `<article class="catalog-card" style="--tier-color:${w.color}"><div class="catalog-card-top"><span>${weaponCategory(kind)}</span><b>${w.tierName}</b></div>${icon(w.icon,w.color)}<h3>${escape(w.name)}</h3><p class="weapon-flavor">${escape(weaponFlavor(kind,tier))}</p><div class="catalog-numbers"><span>伤害 ${Math.round(w.damage)}</span><span>${(1/w.interval).toFixed(1)} 次/秒</span><span>射程 ${Math.round(w.range)}</span></div><div class="catalog-special">${escape(weaponEffectText(w))}</div></article>`;}).join('');}
