  $('run-goal').textContent=state.endless?'无尽生存 · 挑战更高纪录':'20 分钟'+MAPS[state.map||'cemetery'].name+'撤离';$('run-milestone').textContent=state.milestone||'';$('run-progress').style.width=Math.min(100,(state.survivalTime||0)/1200*100)+'%';$('run-streak').textContent=state.streak>=5?`✦ ${state.streak} 连杀`:`本局最高 ${state.bestStreak||0} 连杀`;
