  $('xp-description').textContent=p.pendingUpgrades?`还有 ${p.pendingUpgrades} 次升级奖励待选择 · 下一次升级需要 ${p.xpNeeded} XP`:`距离 LV ${p.level+1} 还需 ${p.xpNeeded-p.xp} XP · 本局累计 ${p.totalXp} XP`;
  const done=['victory','defeat'].includes(phase);$('ready-button').disabled=['battle','upgrade','event'].includes(phase) || (canEquip() && p.pendingUpgrades>0);$('ready-button').classList.toggle('waiting',p.ready);
