  if(done){const summary=p.settlement||career.profile?.history.find(h=>h.id===state.runId),key=JSON.stringify([phase,state.kills,summary,p.continueReady,state.players.map(v=>v.continueReady)]);if($('result').dataset.key!==key){$('result').dataset.key=key;$('result').innerHTML=`<span class="eyebrow">${phase==='victory'?'DAWN HAS ARRIVED':'EVERY RUN COUNTS'}</span><h2>${phase==='victory'?MAPS[state.map||'cemetery'].name+'撤离成功':'小队失守'}</h2><p>${clock(state.survivalTime||state.time)} · LV ${p.level} · ${p.kills} 击杀 · 首领 ${state.bossKills||0}<br>${summary?`本次 +${summary.awarded??0} 零件 · +${summary.goldAwarded??0} 金币 · 成长已保存`:'正在结算成长…'}</p>${runHighlights(summary,career.profile)}<div class="result-actions"><button id="view-report" class="secondary">查看构筑与结算</button><button id="result-career" class="secondary">薪火传承 →</button><button id="restart-result" class="primary">再来一局 ↻</button>${phase==='victory'&&state.campaign&&!state.endless?`<button id="endless-result" class="secondary">${p.continueReady?'已准备 · 等待队友':'继续无尽模式 →'}</button>`:''}</div>`;$('restart-result').onclick=()=>send({type:'restart'});$('result-career').onclick=career.open;$('view-report').onclick=()=>{$('report-title').textContent=phase==='victory'?'墓园撤离成功':'这局的构筑';$('report-body').innerHTML=reportMarkup(summary);$('run-report').showModal();};if($('endless-result'))$('endless-result').onclick=()=>send({type:'continueEndless'});}$('result').classList.remove('hidden');}else{$('result').classList.add('hidden');$('result').dataset.key='';}

